create policy "ava public materials readable" on public.ava_materials for select to anon, authenticated using (is_public = true);
create policy "ava enrolled assessments readable" on public.ava_assessments for select to authenticated using (exists (select 1 from public.ava_lessons l join public.ava_modules m on m.id = l.module_id join public.ava_enrollments e on e.course_id = m.course_id where l.id = lesson_id and e.user_id = (select auth.uid()) and e.status in ('active','completed')));
create policy "ava enrolled questions readable" on public.ava_questions for select to authenticated using (exists (select 1 from public.ava_assessments a join public.ava_lessons l on l.id = a.lesson_id join public.ava_modules m on m.id = l.module_id join public.ava_enrollments e on e.course_id = m.course_id where a.id = assessment_id and e.user_id = (select auth.uid()) and e.status in ('active','completed')));
create policy "ava visible live classes readable" on public.ava_live_classes for select to anon, authenticated using (access_policy = 'public' or ((select auth.uid()) is not null and exists (select 1 from public.ava_enrollments e where e.course_id = ava_live_classes.course_id and e.user_id = (select auth.uid()) and e.status in ('active','completed'))));
create policy "ava published recordings readable" on public.ava_recordings for select to authenticated using (published = true and exists (select 1 from public.ava_live_classes lc join public.ava_enrollments e on e.course_id = lc.course_id where lc.id = live_class_id and e.user_id = (select auth.uid()) and e.status in ('active','completed')));
